// IANA time zone id -> Windows time zone id, from CLDR's windowsZones table
// (WindowsZoneMap.cpp is generated by tools/gen-windows-zones.ps1).
#pragma once
#include <span>
#include <string_view>

struct WindowsZoneEntry {
    std::string_view iana;
    const wchar_t*   windows;   // a key under HKLM\...\Time Zones
};

// The Windows id for an IANA id, including its aliases ("Asia/Kolkata" and
// "Asia/Calcutta"); nullptr when there is none. Exact, case-sensitive match,
// as the names are stored in config.json.
const wchar_t* WindowsZoneId(std::string_view iana);

// Every entry, sorted by IANA id; for tests that check the whole table.
std::span<const WindowsZoneEntry> AllWindowsZones();
